// SPDX-License-Identifier: MIT
//! Replays the frozen TA-Lib 0.8.3 answers in `testdata/talib_vectors.zig`
//! (generated by `tools/interop.zig --emit-vectors`, which drives TA-Lib live)
//! against this module: same lookback, a NaN lead, and every value bitwise equal
//! (the live oracle's per-function ULP bound is 0 for all seed functions; the
//! file carries the bounds and this test refuses a nonzero one it does not know
//! how to apply). `f32` records are TA_S_*: f32 input, TA-Lib's double output,
//! compared with ours after one rounding to f32.

const std = @import("std");
const ind = @import("root.zig");
const vecs = @import("testdata/talib_vectors.zig");
const testing = std.testing;

const max_n = 64;
const n_overlap = 44; // functions 0..43: seed set and overlap studies
const n_func = 94;

fn mt(x: i32) ind.MaType {
    return @fromBackingInt(@intCast(@as(u8, @intCast(x))));
}
fn us(x: i32) usize {
    return @intCast(x);
}

/// Inputs of function `f`: 0 close; 1 high+low; 2 high+low+close; 3 close+aux (volume or periods).
fn inKind(f: u8) u8 {
    return switch (f) {
        9, 10, 11, 12, 13, 27, 29, 34, 37 => 2,
        23, 24, 25, 30, 31, 33, 42 => 1,
        41, 26 => 3,
        else => 0,
    };
}

/// Same table as the `Func` enum of tools/interop.zig.
fn run(comptime T: type, v: vecs.Vec, h: []const T, l: []const T, c: []const T, au: []const T, o: *[4][]T) !usize {
    const ip = v.ip;
    const un: ind.Unstable = switch (v.ukind) {
        0 => .{ .bars = v.ubars },
        1 => .auto4,
        else => .auto8,
    };
    var dp: [8]f64 = undefined;
    for (&dp, v.dp) |*d, b| d.* = @bitCast(b);
    const a = testing.allocator;
    const n = c.len;
    return switch (v.func) {
        0 => ind.sma(T, c, o[0], .{ .period = us(ip[0]) }),
        1 => ind.ema(T, c, o[0], .{ .period = us(ip[0]), .unstable = un }),
        2 => ind.wma(T, c, o[0], .{ .period = us(ip[0]) }),
        3 => ind.ma(T, c, o[0], .{ .period = us(ip[0]), .kind = mt(ip[1]), .unstable = un }),
        4 => ind.macd(T, c, o[0], o[1], o[2], .{ .fast = us(ip[0]), .slow = us(ip[1]), .signal = us(ip[2]), .unstable = un }),
        5 => ind.macdext(T, a, c, o[0], o[1], o[2], .{ .fast = us(ip[0]), .fast_ma = mt(ip[1]), .slow = us(ip[2]), .slow_ma = mt(ip[3]), .signal = us(ip[4]), .signal_ma = mt(ip[5]), .unstable = un }),
        6 => ind.macdfix(T, c, o[0], o[1], o[2], .{ .signal = us(ip[0]), .unstable = un }),
        7 => ind.rsi(T, c, o[0], .{ .period = us(ip[0]), .unstable = un }),
        8 => ind.bbands(T, c, o[0], o[1], o[2], .{ .period = us(ip[0]), .dev_up = dp[0], .dev_dn = dp[1], .ma = mt(ip[1]), .unstable = un }),
        9 => ind.trange(T, h, l, c, o[0]),
        10 => ind.atr(T, h, l, c, o[0], .{ .period = us(ip[0]), .unstable = un }),
        11 => ind.natr(T, h, l, c, o[0], .{ .period = us(ip[0]), .unstable = un }),
        12 => ind.stoch(T, a, h, l, c, o[0], o[1], .{ .fastk = us(ip[0]), .slowk = us(ip[1]), .slowk_ma = mt(ip[2]), .slowd = us(ip[3]), .slowd_ma = mt(ip[4]), .unstable = un }),
        13 => ind.stochf(T, a, h, l, c, o[0], o[1], .{ .fastk = us(ip[0]), .fastd = us(ip[1]), .fastd_ma = mt(ip[2]), .unstable = un }),
        14 => ind.max(T, c, o[0], .{ .period = us(ip[0]) }),
        15 => ind.min(T, c, o[0], .{ .period = us(ip[0]) }),
        16 => ind.sum(T, c, o[0], .{ .period = us(ip[0]) }),
        17 => ind.dema(T, c, o[0], .{ .period = us(ip[0]), .unstable = un }),
        18 => ind.tema(T, c, o[0], .{ .period = us(ip[0]), .unstable = un }),
        19 => ind.t3(T, c, o[0], .{ .period = us(ip[0]), .vfactor = dp[0], .unstable = un }),
        20 => ind.trima(T, c, o[0], .{ .period = us(ip[0]) }),
        21 => ind.kama(T, c, o[0], .{ .period = us(ip[0]), .unstable = un }),
        22 => ind.midpoint(T, c, o[0], .{ .period = us(ip[0]) }),
        23 => ind.midprice(T, h, l, o[0], .{ .period = us(ip[0]) }),
        24 => ind.sar(T, h, l, o[0], .{ .acceleration = dp[0], .maximum = dp[1] }),
        25 => ind.sarext(T, h, l, o[0], .{ .start_value = dp[0], .offset_on_reverse = dp[1], .af_init_long = dp[2], .af_long = dp[3], .af_max_long = dp[4], .af_init_short = dp[5], .af_short = dp[6], .af_max_short = dp[7] }),
        26 => ind.mavp(T, c, au, o[0], .{ .min_period = us(ip[0]), .max_period = us(ip[1]), .kind = mt(ip[2]), .unstable = un }),
        27 => ind.accbands(T, h, l, c, o[0], o[1], o[2], .{ .period = us(ip[0]) }),
        28 => ind.alma(T, a, c, o[0], .{ .period = us(ip[0]), .sigma = dp[0], .offset = dp[1] }),
        29 => ind.cksp(T, a, h, l, c, o[0], o[1], .{ .period = us(ip[0]), .stop_period = us(ip[1]), .multiplier = dp[0], .unstable = un }),
        30 => ind.donchian(T, h, l, o[0], o[1], o[2], .{ .period = us(ip[0]) }),
        31 => ind.frama(T, h, l, o[0], .{ .period = us(ip[0]), .unstable = un }),
        32 => ind.hma(T, c, o[0], .{ .period = us(ip[0]) }),
        33 => ind.ichimoku(T, h, l, o[0], o[1], o[2], o[3], .{ .tenkan = us(ip[0]), .kijun = us(ip[1]), .senkou_b = us(ip[2]) }),
        34 => ind.kc(T, h, l, c, o[0], o[1], o[2], .{ .period = us(ip[0]), .atr_period = us(ip[1]), .nb_dev = dp[0], .unstable = un }),
        35 => ind.mcgd(T, c, o[0], .{ .period = us(ip[0]), .unstable = un }),
        36 => ind.rma(T, c, o[0], .{ .period = us(ip[0]), .unstable = un }),
        37 => blk: {
            var tr: [max_n]i8 = undefined;
            const lb = try ind.supertrend(T, h, l, c, o[0], tr[0..n], .{ .period = us(ip[0]), .multiplier = dp[0], .unstable = un });
            for (o[1][0..n], tr[0..n], 0..) |*d, t, i| d.* = if (i < lb) std.math.nan(T) else @floatFromInt(t);
            break :blk lb;
        },
        38 => ind.swakButter(T, c, o[0], .{ .period = us(ip[0]), .unstable = un }),
        39 => ind.swakGauss(T, c, o[0], .{ .period = us(ip[0]), .unstable = un }),
        40 => ind.vidya(T, c, o[0], .{ .period = us(ip[0]), .cmo_period = us(ip[1]), .unstable = un }),
        41 => ind.vwma(T, c, au, o[0], .{ .period = us(ip[0]) }),
        42 => blk: {
            var tr: [max_n]i8 = undefined;
            var pv: [max_n]i32 = undefined;
            const lb = try ind.zigzag(T, h, l, o[0], tr[0..n], pv[0..n], .{ .sensitivity = dp[0], .min_trend_length = us(ip[0]) });
            for (o[1][0..n], o[2][0..n], tr[0..n], pv[0..n], 0..) |*d, *e, t, pp, i| {
                d.* = if (i < lb) std.math.nan(T) else @floatFromInt(t);
                e.* = if (i < lb) std.math.nan(T) else @floatFromInt(pp);
            }
            break :blk lb;
        },
        43 => ind.zlema(T, c, o[0], .{ .period = us(ip[0]), .unstable = un }),
        else => error.BadParam,
    };
}

/// Function ids of the volume / statistic waves (after the 44 seed and overlap functions), same order as the `Func` enum of tools/interop.zig.
const Fv = enum(u8) {
    ad = n_overlap,
    adosc,
    cmf,
    efi,
    emv,
    kvo,
    marketfi,
    nvi,
    obv,
    pvi,
    pvo,
    pvt,
    rvol,
    vwap,
    adr,
    bbw,
    cvi,
    massi,
    percentb,
    rogerssatchell,
    rvi,
    rvir,
    avgdev,
    avgprice,
    ha,
    medprice,
    typprice,
    wclprice,
    beta,
    correl,
    kurtosis,
    linearreg,
    linearreg_angle,
    linearreg_intercept,
    linearreg_slope,
    median,
    percentile,
    percentrank,
    stddev,
    tsf,
    @"var",
    add,
    cumsum,
    div,
    maxindex,
    minindex,
    minmax,
    minmaxindex,
    mult,
    sub,
};

/// The later waves: `x[k]` is the k-th input series in the order of the C
/// prototype (see `seriesOf` in tools/interop.zig: o/h/l/c/v letters).
fn runVs(comptime T: type, v: vecs.Vec, x: [5][]const T, o: *[4][]T, io: *[2][]usize) !usize {
    const ip = v.ip;
    const un: ind.Unstable = switch (v.ukind) {
        0 => .{ .bars = v.ubars },
        1 => .auto4,
        else => .auto8,
    };
    const dp0: f64 = @bitCast(v.dp[0]);
    const dp1: f64 = @bitCast(v.dp[1]);
    const a = testing.allocator;
    const f: Fv = @fromBackingInt(@intCast(v.func));
    return switch (f) {
        .ad => ind.ad(T, x[0], x[1], x[2], x[3], o[0]),
        .adosc => ind.adosc(T, x[0], x[1], x[2], x[3], o[0], .{ .fast = us(ip[0]), .slow = us(ip[1]), .unstable = un }),
        .cmf => ind.cmf(T, x[0], x[1], x[2], x[3], o[0], .{ .period = us(ip[0]) }),
        .efi => ind.efi(T, x[0], x[1], o[0], .{ .period = us(ip[0]), .unstable = un }),
        .emv => ind.emv(T, x[0], x[1], x[2], o[0], .{ .period = us(ip[0]), .divisor = dp0 }),
        .kvo => ind.kvo(T, x[0], x[1], x[2], x[3], o[0], o[1], .{ .fast = us(ip[0]), .slow = us(ip[1]), .signal = us(ip[2]), .unstable = un }),
        .marketfi => ind.marketfi(T, x[0], x[1], x[2], o[0]),
        .nvi => ind.nvi(T, x[0], x[1], o[0]),
        .obv => ind.obv(T, x[0], x[1], o[0]),
        .pvi => ind.pvi(T, x[0], x[1], o[0]),
        .pvo => ind.pvo(T, x[0], o[0], .{ .fast = us(ip[0]), .slow = us(ip[1]), .ma = mt(ip[2]), .unstable = un }),
        .pvt => ind.pvt(T, x[0], x[1], o[0]),
        .rvol => ind.rvol(T, x[0], o[0], .{ .period = us(ip[0]) }),
        .vwap => ind.vwap(T, x[0], x[1], x[2], x[3], o[0]),
        .adr => ind.adr(T, x[0], x[1], o[0], .{ .period = us(ip[0]) }),
        .bbw => ind.bbw(T, x[0], o[0], .{ .period = us(ip[0]), .dev_up = dp0, .dev_dn = dp1, .ma = mt(ip[1]), .unstable = un }),
        .cvi => ind.cvi(T, x[0], x[1], o[0], .{ .period = us(ip[0]), .roc = us(ip[1]), .unstable = un }),
        .massi => ind.massi(T, x[0], x[1], o[0], .{ .fast = us(ip[0]), .slow = us(ip[1]), .unstable = un }),
        .percentb => ind.percentb(T, x[0], o[0], .{ .period = us(ip[0]), .dev_up = dp0, .dev_dn = dp1, .ma = mt(ip[1]), .unstable = un }),
        .rogerssatchell => ind.rogerssatchell(T, x[0], x[1], x[2], x[3], o[0], .{ .period = us(ip[0]), .annualization = dp0 }),
        .rvi => ind.rvi(T, x[0], o[0], .{ .period = us(ip[0]), .stddev = us(ip[1]), .unstable = un }),
        .rvir => ind.rvir(T, x[0], x[1], o[0], .{ .period = us(ip[0]), .stddev = us(ip[1]), .unstable = un }),
        .avgdev => ind.avgdev(T, x[0], o[0], .{ .period = us(ip[0]) }),
        .avgprice => ind.avgprice(T, x[0], x[1], x[2], x[3], o[0]),
        .ha => ind.ha(T, x[0], x[1], x[2], x[3], o[0], o[1], o[2], o[3], .{ .unstable = un }),
        .medprice => ind.medprice(T, x[0], x[1], o[0]),
        .typprice => ind.typprice(T, x[0], x[1], x[2], o[0]),
        .wclprice => ind.wclprice(T, x[0], x[1], x[2], o[0]),
        .beta => ind.beta(T, x[0], x[1], o[0], .{ .period = us(ip[0]) }),
        .correl => ind.correl(T, x[0], x[1], o[0], .{ .period = us(ip[0]) }),
        .kurtosis => ind.kurtosis(T, x[0], o[0], .{ .period = us(ip[0]) }),
        .linearreg => ind.linearreg(T, x[0], o[0], .{ .period = us(ip[0]) }),
        .linearreg_angle => ind.linearregAngle(T, x[0], o[0], .{ .period = us(ip[0]) }),
        .linearreg_intercept => ind.linearregIntercept(T, x[0], o[0], .{ .period = us(ip[0]) }),
        .linearreg_slope => ind.linearregSlope(T, x[0], o[0], .{ .period = us(ip[0]) }),
        .median => ind.median(T, a, x[0], o[0], .{ .period = us(ip[0]) }),
        .percentile => ind.percentile(T, a, x[0], o[0], .{ .period = us(ip[0]), .percentile = dp0 }),
        .percentrank => ind.percentrank(T, x[0], o[0], .{ .period = us(ip[0]) }),
        .stddev => ind.stddev(T, x[0], o[0], .{ .period = us(ip[0]), .nbdev = dp0 }),
        .tsf => ind.tsf(T, x[0], o[0], .{ .period = us(ip[0]) }),
        .@"var" => ind.variance(T, x[0], o[0], .{ .period = us(ip[0]), .nbdev = dp0 }),
        .add => ind.add(T, x[0], x[1], o[0]),
        .sub => ind.sub(T, x[0], x[1], o[0]),
        .mult => ind.mult(T, x[0], x[1], o[0]),
        .div => ind.div(T, x[0], x[1], o[0]),
        .cumsum => ind.cumsum(T, x[0], o[0]),
        .maxindex => ind.maxindex(T, x[0], io[0], .{ .period = us(ip[0]) }),
        .minindex => ind.minindex(T, x[0], io[0], .{ .period = us(ip[0]) }),
        .minmax => ind.minmax(T, x[0], o[0], o[1], .{ .period = us(ip[0]) }),
        .minmaxindex => ind.minmaxindex(T, x[0], io[0], io[1], .{ .period = us(ip[0]) }),
    };
}

fn isIndexFunc(func: u8) bool {
    return func == @backingInt(Fv.maxindex) or func == @backingInt(Fv.minindex) or func == @backingInt(Fv.minmaxindex);
}

/// Distance in ULPs of the output type (NaN against NaN is 0).
fn ulps(comptime T: type, a: T, b: T) u64 {
    if (std.math.isNan(a) and std.math.isNan(b)) return 0;
    if (std.math.isNan(a) or std.math.isNan(b)) return std.math.maxInt(u64);
    const U = if (T == f32) u32 else u64;
    const I = if (T == f32) i32 else i64;
    const key = struct {
        fn of(x: T) i64 {
            const bits: U = @bitCast(x);
            const sign = @as(U, 1) << (@bitSizeOf(U) - 1);
            if (bits & sign != 0) return -@as(i64, @as(I, @intCast(bits & ~sign)));
            return @as(i64, @as(I, @intCast(bits)));
        }
    }.of;
    return @abs(key(a) - key(b));
}

fn replay(comptime T: type, v: vecs.Vec) !void {
    const n: usize = v.n;
    try testing.expect(n <= max_n);
    var ib: [5][max_n]T = undefined;
    var ob: [4][max_n]T = undefined;
    var ub: [2][max_n]usize = undefined;
    for (v.ins, 0..) |col, q| for (col, 0..) |bits, i| {
        ib[q][i] = @floatCast(@as(f64, @bitCast(bits)));
    };
    var o: [4][]T = .{ ob[0][0..n], ob[1][0..n], ob[2][0..n], ob[3][0..n] };
    var io: [2][]usize = .{ ub[0][0..n], ub[1][0..n] };
    var lb: usize = undefined;
    if (v.func < n_overlap) {
        const h: []const T = ib[0][0..n];
        var l: []const T = ib[0][0..n];
        var c: []const T = ib[0][0..n];
        var au: []const T = ib[0][0..n];
        switch (inKind(v.func)) {
            0 => {},
            1 => l = ib[1][0..n],
            2 => {
                l = ib[1][0..n];
                c = ib[2][0..n];
            },
            else => au = ib[1][0..n],
        }
        lb = try run(T, v, h, l, c, au, &o);
    } else {
        var x: [5][]const T = undefined;
        for (0..5) |q| x[q] = ib[q][0..n];
        lb = try runVs(T, v, x, &o, &io);
    }
    try testing.expectEqual(@as(usize, v.lb), lb);
    const idx = isIndexFunc(v.func);
    const bound = vecs.ulp_bound[v.func];
    for (v.outs, 0..) |col, q| {
        if (idx) {
            for (io[q][0..@min(lb, n)]) |x| try testing.expectEqual(ind.no_index, x);
        } else {
            for (o[q][0..@min(lb, n)]) |x| try testing.expect(std.math.isNan(x));
        }
        try testing.expectEqual(if (n > lb) n - lb else 0, col.len);
        for (col, 0..) |bits, i| {
            const want64: f64 = @bitCast(bits);
            if (idx) {
                const got: f64 = @floatFromInt(io[q][lb + i]);
                try testing.expectEqual(want64, got);
                continue;
            }
            const want: T = @floatCast(want64);
            const got = o[q][lb + i];
            const d = ulps(T, got, want);
            const same_zero_sign = std.math.signbit(got) == std.math.signbit(want) or std.math.isNan(want);
            if (d > bound or (bound == 0 and !same_zero_sign)) {
                std.debug.print("vector func {d} ip {any} n {d}: output {d} at {d}: ours {e} TA-Lib {e}\n", .{ v.func, v.ip, v.n, q, lb + i, got, want });
                return error.TestExpectedEqual;
            }
        }
    }
}

test "frozen TA-Lib vectors: every function, f64 and f32, unstable levels" {
    try testing.expectEqual(@as(usize, n_func), vecs.ulp_bound.len);
    // a nonzero bound is applied as ULPs of the output type; the only one is LINEARREG_ANGLE's `atan`
    for (vecs.ulp_bound, 0..) |b, k| {
        if (k == @backingInt(Fv.linearreg_angle)) {
            try testing.expectEqual(@as(u64, 2), b);
        } else try testing.expectEqual(@as(u64, 0), b);
    }
    var seen: [vecs.ulp_bound.len]usize = @splat(0);
    for (vecs.vectors) |v| {
        if (v.f32) try replay(f32, v) else try replay(f64, v);
        for (v.outs) |col| seen[v.func] += col.len;
    }
    // every function contributed values to compare, not only empty lookback cases
    for (seen) |k| try testing.expect(k >= 20);
}
